window.AUTH={loggedIn:!1,hasPaid:!1,email:null},window.META=[];const EXAM_PRICE_DISPLAY="₹10";async function initAuthAndQuestions(){try{const[n,t]=await Promise.all([fetch("/api/me",{credentials:"same-origin"}),fetch("/api/meta")]);n.ok&&(window.AUTH=await n.json()),t.ok&&(window.META=await t.json())}catch(n){console.warn("Auth/meta check failed — continuing with free sample only.",n)}if(window.AUTH.hasPaid)try{const n=await fetch("/api/questions",{credentials:"same-origin"});n.ok&&(window.SUBJECTS=await n.json())}catch(n){console.warn("Could not load full question bank — showing free sample.",n)}window.__ffaSetWatermark&&window.__ffaSetWatermark(window.AUTH.loggedIn?window.AUTH.email:null)}function metaFor(n,t){const o=(window.META||[]).find(t=>t.id===n);return o&&(o.chapters||[]).find(n=>n.id===t)||null}function loadRazorpayScript(){return new Promise((n,t)=>{if(window.Razorpay)return n();const o=document.createElement("script");o.src="https://checkout.razorpay.com/v1/checkout.js",o.onload=n,o.onerror=()=>t(new Error("Could not load payment gateway. Check your connection.")),document.head.appendChild(o)})}async function startCheckout(){if(window.AUTH.loggedIn)try{await loadRazorpayScript();const n=await fetch("/api/create-order",{method:"POST",credentials:"same-origin"}),t=await n.json();if(!n.ok)throw new Error(t.error||"Could not start payment.");if(t.alreadyPaid)return window.AUTH.hasPaid=!0,void window.location.reload();const o=new Razorpay({key:t.keyId,order_id:t.orderId,amount:t.amount,currency:t.currency,name:"Flight Flare Aviation",description:"DGCA Exam Bank — Full Access",image:"logo1.png",prefill:{email:window.AUTH.email||""},theme:{color:"#4FD1C5"},handler:async function(n){try{const t=await fetch("/api/verify-payment",{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify(n)}),o=await t.json();if(!t.ok)throw new Error(o.error||"Payment verification failed.");window.AUTH.hasPaid=!0,alert("Payment successful — full question bank unlocked!"),window.location.reload()}catch(t){alert(t.message+"\n\nIf money was deducted, contact us and we'll sort it out — your payment ID is "+n.razorpay_payment_id)}},modal:{ondismiss:function(){}}});o.on("payment.failed",function(n){alert("Payment failed: "+(n.error&&n.error.description?n.error.description:"please try again."))}),o.open()}catch(n){alert(n.message)}else window.location.href="login.html?next="+encodeURIComponent("index.html")}async function logout(){await fetch("/api/logout",{method:"POST",credentials:"same-origin"}),window.location.href="index.html"}function renderAccountWidget(){const n=document.getElementById("ff-account-widget");if(!n)return;if(!window.AUTH.loggedIn)return void(n.innerHTML='<a href="login.html" class="btn btn-ghost btn-sm">Log in</a>');if(window.AUTH.hasPaid)n.innerHTML=`\n      <span class="chip chip-success" title="${window.AUTH.email}">Full access</span>\n      <button class="btn btn-ghost btn-sm" id="ff-logout-btn">Log out</button>\n    `;else{n.innerHTML='\n      <button class="btn btn-primary btn-sm" id="ff-unlock-btn">Unlock full access &middot; ₹10</button>\n      <button class="btn btn-ghost btn-sm" id="ff-logout-btn">Log out</button>\n    ';const t=document.getElementById("ff-unlock-btn");t&&t.addEventListener("click",startCheckout)}const t=document.getElementById("ff-logout-btn");t&&t.addEventListener("click",logout)}